// Builds Parquet files from Citi Bike CSV trip data with embedded route geometries.
//
// Usage: bun run build-parquet.ts
//
// Processes ALL CSV files in data/**/*.csv in a single pass, handling both
// legacy (2013-2019) and modern (2020+) schemas automatically.
//
// Prerequisites:
// - CSV files in data/**/*.csv
// - output/routes.db (from build-routes.ts)
// - apps/client/public/stations.json (from build-stations.ts)
//
// Output:
// - output/parquets/<year>-<month>-<day>.parquet for each day with data
import { DuckDBConnection } from "@duckdb/node-api";
import { globSync } from "glob";
import { mkdir, readdir, rename, rm, rmdir, stat } from "node:fs/promises";
import path from "path";
import { csvGlob, dataDir, formatHumanReadableBytes, gitRoot, NYC_BOUNDS, outputDir } from "./utils";

const routesDbPath = path.join(outputDir, "routes.db");

type ValidationResult = {
  total_rows: bigint;
  null_ride_id: bigint;
  null_start_station_name: bigint;
  null_end_station_name: bigint;
  null_started_at: bigint;
  null_ended_at: bigint;
  null_start_lat: bigint;
  null_start_lng: bigint;
  null_end_lat: bigint;
  null_end_lng: bigint;
  null_rideable_type: bigint;
  null_member_casual: bigint;
  unparseable_started_at: bigint;
  unparseable_ended_at: bigint;
  unparseable_start_lat: bigint;
  unparseable_start_lng: bigint;
  unparseable_end_lat: bigint;
  unparseable_end_lng: bigint;
  invalid_rideable_type: bigint;
  invalid_member_casual: bigint;
  end_before_start: bigint;
};

function printValidationWarnings(v: ValidationResult): void {
  const warnings: string[] = [];
  const total = Number(v.total_rows);

  const fmt = (count: bigint, msg: string) => {
    const pct = ((Number(count) / total) * 100).toFixed(2);
    return `${count} rows (${pct}%) with ${msg}`;
  };

  // NULL checks
  if (v.null_ride_id > 0) warnings.push(fmt(v.null_ride_id, "NULL ride_id"));
  if (v.null_start_station_name > 0) warnings.push(fmt(v.null_start_station_name, "NULL start_station_name"));
  if (v.null_end_station_name > 0) warnings.push(fmt(v.null_end_station_name, "NULL end_station_name"));
  if (v.null_started_at > 0) warnings.push(fmt(v.null_started_at, "NULL started_at"));
  if (v.null_ended_at > 0) warnings.push(fmt(v.null_ended_at, "NULL ended_at"));
  if (v.null_start_lat > 0) warnings.push(fmt(v.null_start_lat, "NULL start_lat"));
  if (v.null_start_lng > 0) warnings.push(fmt(v.null_start_lng, "NULL start_lng"));
  if (v.null_end_lat > 0) warnings.push(fmt(v.null_end_lat, "NULL end_lat"));
  if (v.null_end_lng > 0) warnings.push(fmt(v.null_end_lng, "NULL end_lng"));
  if (v.null_rideable_type > 0) warnings.push(fmt(v.null_rideable_type, "NULL rideable_type"));
  if (v.null_member_casual > 0) warnings.push(fmt(v.null_member_casual, "NULL member_casual"));

  // Type/parse checks
  if (v.unparseable_started_at > 0) warnings.push(fmt(v.unparseable_started_at, "unparseable started_at"));
  if (v.unparseable_ended_at > 0) warnings.push(fmt(v.unparseable_ended_at, "unparseable ended_at"));
  if (v.unparseable_start_lat > 0) warnings.push(fmt(v.unparseable_start_lat, "unparseable start_lat"));
  if (v.unparseable_start_lng > 0) warnings.push(fmt(v.unparseable_start_lng, "unparseable start_lng"));
  if (v.unparseable_end_lat > 0) warnings.push(fmt(v.unparseable_end_lat, "unparseable end_lat"));
  if (v.unparseable_end_lng > 0) warnings.push(fmt(v.unparseable_end_lng, "unparseable end_lng"));

  // Enum checks
  if (v.invalid_rideable_type > 0) warnings.push(fmt(v.invalid_rideable_type, "invalid rideable_type (must be 'classic_bike' or 'electric_bike')"));
  if (v.invalid_member_casual > 0) warnings.push(fmt(v.invalid_member_casual, "invalid member_casual (must be 'member' or 'casual')"));

  // Logic checks
  if (v.end_before_start > 0) warnings.push(fmt(v.end_before_start, "ended_at before started_at"));

  if (warnings.length > 0) {
    console.warn(`\nValidation warnings (rows will be dropped):\n  - ${warnings.join("\n  - ")}`);
  } else {
    console.log("No validation issues found.");
  }
}

async function main() {
  console.log("Starting parquet build (single-pass, all years)...");
  console.log(`Data directory: ${dataDir}`);
  console.log(`Output directory: ${outputDir}`);

  // Ensure output directories exist
  await mkdir(path.join(outputDir, "parquets"), { recursive: true });

  const connection = await DuckDBConnection.create();

  // Configure DuckDB for large workloads - spill to disk when needed
  const tempDir = path.join(outputDir, "duckdb_tmp");
  await mkdir(tempDir, { recursive: true });
  await connection.run(`SET temp_directory = '${tempDir}'`);

  // 1. Load ALL data from all years using unified schema
  // Uses COALESCE to handle both legacy (2013-2019) and modern (2020+) schemas
  console.log(`\nReading CSVs matching: ${csvGlob}`);

  // Expand glob so we can report inputs deterministically
  const matchedCsvs = globSync(csvGlob, { nodir: true });
  if (matchedCsvs.length === 0) {
    throw new Error(`No CSV files matched: ${csvGlob}`);
  }

  let totalBytes = 0;
  for (const filePath of matchedCsvs) {
    totalBytes += (await stat(filePath)).size;
  }

  console.log(`Matched CSVs: ${matchedCsvs.length}`);
  console.log(matchedCsvs.map((p) => `- ${p}`).join("\n"));
  console.log(`Total input size: ${formatHumanReadableBytes(totalBytes)}`);

  const startTime = Date.now();

  // Unified schema handling:
  // - normalize_names=true converts "Start Station Name" -> start_station_name (merges with legacy)
  // - Legacy lowercase (2013-2018): starttime, start_station_name, usertype
  // - Legacy Title Case (2015-2016): start_time (normalized), start_station_name (merged), user_type
  // - Modern (2020+): started_at, start_station_name, member_casual
  console.log("Loading CSVs with unified schema...");
  await connection.run(`
    CREATE TEMP TABLE raw AS
    SELECT
      -- ID: use ride_id if present, else generate from legacy fields
      COALESCE(ride_id, md5(COALESCE(bikeid, bike_id)::VARCHAR || COALESCE(starttime, start_time::VARCHAR)::VARCHAR)) as ride_id,

      -- Bike type: use rideable_type if present, else 'classic_bike' for legacy
      COALESCE(rideable_type, 'classic_bike') as rideable_type,

      -- Timestamps: all columns are VARCHAR with all_varchar=true
      -- First COALESCE picks first non-null value, then parse
      COALESCE(
        TRY_CAST(started_at AS TIMESTAMP),
        TRY_CAST(start_time AS TIMESTAMP),
        TRY_CAST(starttime AS TIMESTAMP),
        TRY_STRPTIME(COALESCE(started_at, start_time, starttime), '%m/%d/%Y %H:%M:%S'),
        TRY_STRPTIME(COALESCE(started_at, start_time, starttime), '%m/%d/%Y %H:%M')
      ) as started_at,
      COALESCE(
        TRY_CAST(ended_at AS TIMESTAMP),
        TRY_CAST(stop_time AS TIMESTAMP),
        TRY_CAST(stoptime AS TIMESTAMP),
        TRY_STRPTIME(COALESCE(ended_at, stop_time, stoptime), '%m/%d/%Y %H:%M:%S'),
        TRY_STRPTIME(COALESCE(ended_at, stop_time, stoptime), '%m/%d/%Y %H:%M')
      ) as ended_at,

      -- Station names: normalize_names merges Title Case into snake_case
      start_station_name,
      end_station_name,

      -- Coordinates: all columns are VARCHAR with all_varchar=true
      TRY_CAST(COALESCE(start_lat, start_station_latitude) AS DOUBLE) as start_lat,
      TRY_CAST(COALESCE(start_lng, start_station_longitude) AS DOUBLE) as start_lng,
      TRY_CAST(COALESCE(end_lat, end_station_latitude) AS DOUBLE) as end_lat,
      TRY_CAST(COALESCE(end_lng, end_station_longitude) AS DOUBLE) as end_lng,

      -- Member type: normalize legacy 'Subscriber' -> 'member', 'Customer' -> 'casual'
      COALESCE(
        member_casual,
        CASE WHEN COALESCE(usertype, user_type) = 'Subscriber' THEN 'member' ELSE 'casual' END
      ) as member_casual

    FROM read_csv_auto('${csvGlob}', union_by_name=true, normalize_names=true, all_varchar=true, null_padding=true, quote='"')
  `);

  const loadTime = Date.now() - startTime;
  console.log(`Loaded CSVs into temp table in ${(loadTime / 1000).toFixed(1)}s`);

  // Pre-compute output day for efficient filtering
  // This avoids re-computing timezone conversion + string formatting for every row on every day iteration
  console.log("\nPre-computing output days...");
  const precomputeStart = Date.now();
  await connection.run(`
    ALTER TABLE raw ADD COLUMN output_day VARCHAR
  `);
  await connection.run(`
    UPDATE raw SET output_day = strftime(
      timezone('America/New_York', started_at)::TIMESTAMP,
      '%Y-%m-%d'
    )
    WHERE started_at IS NOT NULL
  `);
  console.log("Creating index on output_day...");
  await connection.run(`
    CREATE INDEX idx_output_day ON raw(output_day)
  `);
  const precomputeTime = Date.now() - precomputeStart;
  console.log(`Pre-computed output days in ${(precomputeTime / 1000).toFixed(1)}s`);

  // 2. Validate data
  console.log("\nValidating data...");

  const validationReader = await connection.runAndReadAll(`
    SELECT
      -- NULL checks
      COUNT(*) FILTER (WHERE ride_id IS NULL) as null_ride_id,
      COUNT(*) FILTER (WHERE start_station_name IS NULL) as null_start_station_name,
      COUNT(*) FILTER (WHERE end_station_name IS NULL) as null_end_station_name,
      COUNT(*) FILTER (WHERE started_at IS NULL) as null_started_at,
      COUNT(*) FILTER (WHERE ended_at IS NULL) as null_ended_at,
      COUNT(*) FILTER (WHERE start_lat IS NULL) as null_start_lat,
      COUNT(*) FILTER (WHERE start_lng IS NULL) as null_start_lng,
      COUNT(*) FILTER (WHERE end_lat IS NULL) as null_end_lat,
      COUNT(*) FILTER (WHERE end_lng IS NULL) as null_end_lng,
      COUNT(*) FILTER (WHERE rideable_type IS NULL) as null_rideable_type,
      COUNT(*) FILTER (WHERE member_casual IS NULL) as null_member_casual,

      -- Type checks (TRY_CAST returns NULL if unparseable)
      COUNT(*) FILTER (WHERE TRY_CAST(started_at AS TIMESTAMP) IS NULL AND started_at IS NOT NULL) as unparseable_started_at,
      COUNT(*) FILTER (WHERE TRY_CAST(ended_at AS TIMESTAMP) IS NULL AND ended_at IS NOT NULL) as unparseable_ended_at,
      COUNT(*) FILTER (WHERE TRY_CAST(start_lat AS DOUBLE) IS NULL AND start_lat IS NOT NULL) as unparseable_start_lat,
      COUNT(*) FILTER (WHERE TRY_CAST(start_lng AS DOUBLE) IS NULL AND start_lng IS NOT NULL) as unparseable_start_lng,
      COUNT(*) FILTER (WHERE TRY_CAST(end_lat AS DOUBLE) IS NULL AND end_lat IS NOT NULL) as unparseable_end_lat,
      COUNT(*) FILTER (WHERE TRY_CAST(end_lng AS DOUBLE) IS NULL AND end_lng IS NOT NULL) as unparseable_end_lng,

      -- Enum checks
      COUNT(*) FILTER (WHERE rideable_type NOT IN ('classic_bike', 'electric_bike')) as invalid_rideable_type,
      COUNT(*) FILTER (WHERE member_casual NOT IN ('member', 'casual')) as invalid_member_casual,

      -- Logic checks
      COUNT(*) FILTER (WHERE ended_at < started_at) as end_before_start,

      -- Total
      COUNT(*) as total_rows
    FROM raw
  `);

  const validation = validationReader.getRowObjects()[0] as ValidationResult;
  console.log(`Total rows: ${validation.total_rows}`);

  // Check for duplicates
  const duplicateReader = await connection.runAndReadAll(`
    SELECT COUNT(*) as duplicate_count
    FROM (
      SELECT ride_id
      FROM raw
      GROUP BY ride_id
      HAVING COUNT(*) > 1
    )
  `);

  const duplicateCount = Number(
    (duplicateReader.getRowObjects()[0] as { duplicate_count: bigint }).duplicate_count
  );
  if (duplicateCount > 0) {
    const pct = ((duplicateCount / Number(validation.total_rows)) * 100).toFixed(2);
    console.warn(`\nWarning: ${duplicateCount} duplicate ride_ids (${pct}%) will be deduplicated`);
  }

  // Print validation warnings
  printValidationWarnings(validation);

  // 3. Load routes from SQLite into DuckDB
  console.log("\nLoading routes from SQLite...");
  if (!(await Bun.file(routesDbPath).exists())) {
    throw new Error(`routes.db not found at ${routesDbPath}. Run build-routes.ts first.`);
  }
  await connection.run(`
    INSTALL sqlite;
    LOAD sqlite;
  `);
  await connection.run(`
    CREATE TABLE routes AS
    SELECT * FROM sqlite_scan('${routesDbPath}', 'routes')
  `);
  const routeCountReader = await connection.runAndReadAll(`SELECT COUNT(*) as count FROM routes`);
  const routeCount = Number((routeCountReader.getRowObjects()[0] as { count: bigint }).count);
  console.log(`  ${routeCount} routes loaded`);

  // Load station data from stations.json for route matching
  // Routes are keyed by station NAME (not ID) because station IDs change between years
  const stationsJsonPath = path.join(gitRoot, "apps/client/public/stations.json");
  if (!(await Bun.file(stationsJsonPath).exists())) {
    console.warn(`stations.json not found - trips will have no routes`);
  } else {
    // Create name normalization lookup: maps any name (canonical OR alias) -> canonical name
    // This handles station names that changed over time (e.g., "8 Ave & W 31 St" -> "W 31 St & 8 Ave")
    console.log("\nLoading station name lookup from stations.json...");
    await connection.run(`
      CREATE TABLE station_name_lookup AS
      -- Canonical names map to themselves
      SELECT name as any_name, name as canonical_name
      FROM read_json_auto('${stationsJsonPath}')
      UNION ALL
      -- Aliases map to their canonical name
      SELECT UNNEST(aliases) as any_name, name as canonical_name
      FROM read_json_auto('${stationsJsonPath}')
    `);
    const lookupCountReader = await connection.runAndReadAll(`SELECT COUNT(*) as count FROM station_name_lookup`);
    const lookupCount = Number((lookupCountReader.getRowObjects()[0] as { count: bigint }).count);
    console.log(`  ${lookupCount} name mappings loaded (canonical + aliases)`);
  }

  // 4. Create deduped table with all valid rows (single pass instead of per-day)
  const validRowFilter = `
    ride_id IS NOT NULL
    AND start_station_name IS NOT NULL
    AND end_station_name IS NOT NULL
    AND started_at IS NOT NULL
    AND ended_at IS NOT NULL
    AND start_lat IS NOT NULL
    AND start_lng IS NOT NULL
    AND end_lat IS NOT NULL
    AND end_lng IS NOT NULL
    AND rideable_type IN ('classic_bike', 'electric_bike')
    AND member_casual IN ('member', 'casual')
    AND ended_at >= started_at
    AND start_lat BETWEEN ${NYC_BOUNDS.minLat} AND ${NYC_BOUNDS.maxLat}
    AND start_lng BETWEEN ${NYC_BOUNDS.minLng} AND ${NYC_BOUNDS.maxLng}
    AND end_lat BETWEEN ${NYC_BOUNDS.minLat} AND ${NYC_BOUNDS.maxLat}
    AND end_lng BETWEEN ${NYC_BOUNDS.minLng} AND ${NYC_BOUNDS.maxLng}
  `;

  console.log("\nCreating deduplicated table...");
  const dedupeStart = Date.now();
  await connection.run(`
    CREATE TABLE deduped AS
    SELECT DISTINCT ON (ride_id) *
    FROM raw
    WHERE ${validRowFilter}
      AND output_day IS NOT NULL
  `);
  const dedupeTime = Date.now() - dedupeStart;

  const dedupedCountReader = await connection.runAndReadAll(`SELECT COUNT(*) as count FROM deduped`);
  const dedupedCount = Number((dedupedCountReader.getRowObjects()[0] as { count: bigint }).count);
  console.log(`Created deduped table with ${dedupedCount} rows in ${(dedupeTime / 1000).toFixed(1)}s`);

  // 5. Export all days in parallel using PARTITION_BY
  // DuckDB will parallelize internally and write one file per partition per thread
  console.log("\nExporting parquet files with PARTITION_BY (parallel)...");
  const parquetsDir = path.join(outputDir, "parquets");
  const exportStart = Date.now();

  await connection.run(`
    COPY (
      SELECT
        t.ride_id as id,
        COALESCE(snl_start.canonical_name, t.start_station_name) as startStationName,
        COALESCE(snl_end.canonical_name, t.end_station_name) as endStationName,
        timezone('America/New_York', t.started_at)::TIMESTAMP as startedAt,
        timezone('America/New_York', t.ended_at)::TIMESTAMP as endedAt,
        t.rideable_type as bikeType,
        t.member_casual as memberCasual,
        t.start_lat as startLat,
        t.start_lng as startLng,
        t.end_lat as endLat,
        t.end_lng as endLng,
        r.geometry as routeGeometry,
        r.distance as routeDistance,
        t.output_day
      FROM deduped t
      LEFT JOIN station_name_lookup snl_start
        ON t.start_station_name = snl_start.any_name
      LEFT JOIN station_name_lookup snl_end
        ON t.end_station_name = snl_end.any_name
      LEFT JOIN routes r
        ON r.start_station_name = COALESCE(snl_start.canonical_name, t.start_station_name)
        AND r.end_station_name = COALESCE(snl_end.canonical_name, t.end_station_name)
      WHERE r.geometry IS NOT NULL
      ORDER BY t.output_day, startedAt
    )
    TO '${parquetsDir}' (FORMAT PARQUET, PARTITION_BY (output_day), COMPRESSION ZSTD, ROW_GROUP_SIZE 2048)
  `);

  const exportTime = Date.now() - exportStart;
  console.log(`Partitioned export completed in ${(exportTime / 1000).toFixed(1)}s`);

  // 6. Rename partitioned files from output_day=YYYY-MM-DD/data_0.parquet to YYYY-MM-DD.parquet
  console.log("\nRenaming partitioned files...");
  const partitionDirs = await readdir(parquetsDir);
  let fileCount = 0;

  for (const dir of partitionDirs) {
    if (!dir.startsWith("output_day=")) continue;
    const day = dir.replace("output_day=", "");
    const partitionDir = path.join(parquetsDir, dir);

    // DuckDB may create multiple files per partition (data_0.parquet, data_1.parquet, etc.)
    // We need to find and merge them if multiple exist
    const files = await readdir(partitionDir);
    const parquetFiles = files.filter(f => f.endsWith(".parquet"));

    if (parquetFiles.length === 1) {
      // Single file - just rename
      const srcPath = path.join(partitionDir, parquetFiles[0]!);
      const destPath = path.join(parquetsDir, `${day}.parquet`);
      await rename(srcPath, destPath);
    } else if (parquetFiles.length > 1) {
      // Multiple files - need to merge them
      // This shouldn't happen often with our data volume per day
      console.warn(`  Warning: ${day} has ${parquetFiles.length} files, merging...`);
      const srcGlob = path.join(partitionDir, "*.parquet");
      const destPath = path.join(parquetsDir, `${day}.parquet`);
      await connection.run(`
        COPY (SELECT * FROM read_parquet('${srcGlob}') ORDER BY startedAt)
        TO '${destPath}' (FORMAT PARQUET, COMPRESSION ZSTD, ROW_GROUP_SIZE 2048)
      `);
    }

    // Remove the partition directory
    await rm(partitionDir, { recursive: true });
    fileCount++;
  }
  console.log(`Renamed ${fileCount} partition directories`);

  // 7. Compute final stats
  console.log("\nComputing final statistics...");
  const statsReader = await connection.runAndReadAll(`
    SELECT COUNT(*) as total_with_route
    FROM read_parquet('${parquetsDir}/*.parquet')
  `);
  const totalWithRoute = Number((statsReader.getRowObjects()[0] as { total_with_route: bigint }).total_with_route);

  // Get total parquet size
  let totalParquetBytes = 0;
  const parquetFiles = await readdir(parquetsDir);
  for (const file of parquetFiles) {
    if (file.endsWith(".parquet")) {
      const fileStat = await stat(path.join(parquetsDir, file));
      totalParquetBytes += fileStat.size;
    }
  }

  // Count trips before route join (from deduped table)
  const totalTripCount = dedupedCount;

  // Final summary
  const totalWithoutRoute = totalTripCount - totalWithRoute;
  const droppedCount = Number(validation.total_rows) - totalTripCount;
  const droppedPct = ((droppedCount / Number(validation.total_rows)) * 100).toFixed(2);
  console.warn(`\nTotal data loss: ${droppedCount} rows (${droppedPct}%) dropped`);

  console.log(`\nTotal Parquet output: ${(totalParquetBytes / 1024 / 1024).toFixed(1)} MB`);
  console.log(`  ${totalTripCount} trips total`);
  console.log(`  ${totalWithRoute} with routes (${((totalWithRoute / totalTripCount) * 100).toFixed(1)}%)`);
  console.log(`  ${totalWithoutRoute} without routes`);

  connection.closeSync();

  // Clean up temp directory
  await rm(tempDir, { recursive: true, force: true });

  const totalTime = Date.now() - startTime;
  console.log(`\nDone in ${(totalTime / 1000).toFixed(1)}s`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import { DuckDBConnection } from "@duckdb/node-api";
import booleanPointInPolygon from "@turf/boolean-point-in-polygon";
import distance from "@turf/distance";
import { point } from "@turf/helpers";
import type { Feature, FeatureCollection, Polygon } from "geojson";
import path from "path";
import { csvGlob, dataDir, gitRoot, NYC_BOUNDS } from "./utils";

// Derive station data from raw CSV files + geocode with neighborhood boundaries.
// Clusters stations from ALL years by coordinates to create a unified station list
// with aliases for historical name lookups.
//
// Input:
// - data/**/*.csv (raw Citi Bike trip CSVs from all years)
// - data/d085e2f8d0b54d4590b1e7d1f35594c1pediacitiesnycneighborhoods.geojson
//
// Output:
// - apps/client/public/stations.json

// Distance threshold for clustering stations at same physical location
const CLUSTER_THRESHOLD_METERS = 60;

type NeighborhoodProperties = {
  neighborhood: string;
  borough: string;
};

type NeighborhoodFeature = Feature<Polygon, NeighborhoodProperties>;

type StationRegion = {
  borough: string;
  neighborhood: string;
};

type StationForSearch = {
  name: string;
  aliases: string[]; // Historical names for search matching (excludes canonical name)
  latitude: number;
  longitude: number;
  borough: string;
  neighborhood: string;
};

// Get region for NJ stations (simple bounding box)
function getNJRegion(lat: number, lng: number): StationRegion | null {
  // West of Hudson River = NJ
  if (lng < -74.02) {
    if (lat > 40.735) {
      return { borough: "New Jersey", neighborhood: "Hoboken" };
    }
    return { borough: "New Jersey", neighborhood: "Jersey City" };
  }
  return null;
}

// Get region for NYC stations (point-in-polygon)
function getNYCRegion(
  lat: number,
  lng: number,
  neighborhoods: NeighborhoodFeature[]
): StationRegion | null {
  const stationPoint = point([lng, lat]);

  for (const feature of neighborhoods) {
    if (booleanPointInPolygon(stationPoint, feature.geometry)) {
      return {
        borough: feature.properties.borough,
        neighborhood: feature.properties.neighborhood,
      };
    }
  }
  return null;
}

// Get region for a station
function getStationRegion(
  lat: number,
  lng: number,
  neighborhoods: NeighborhoodFeature[]
): StationRegion {
  // Try NJ first (fast bounding box check)
  const njRegion = getNJRegion(lat, lng);
  if (njRegion) return njRegion;

  // Try NYC (point-in-polygon)
  const nycRegion = getNYCRegion(lat, lng, neighborhoods);
  if (nycRegion) return nycRegion;

  return { borough: "Unknown", neighborhood: "Unknown" };
}

// Raw station data from CSV extraction (before clustering)
type RawStation = {
  name: string;
  latitude: number;
  longitude: number;
  year: number; // Year this name was observed (for canonical name selection)
};

// Cluster stations by coordinates (~50m threshold = same physical location)
// Returns merged stations with aliases
function clusterStationsByCoordinates(data: {
  stations: RawStation[];
  thresholdMeters: number;
}): Array<{
  canonicalName: string;
  aliases: string[];
  latitude: number;
  longitude: number;
}> {
  const { stations, thresholdMeters } = data;
  const clusters: Array<{
    names: Map<string, number>; // name -> latest year seen
    latSum: number;
    lngSum: number;
    count: number;
  }> = [];

  for (const station of stations) {
    // Find nearest cluster within threshold
    let nearestCluster: (typeof clusters)[number] | null = null;
    let nearestDist = Infinity;
    for (const cluster of clusters) {
      const clusterLat = cluster.latSum / cluster.count;
      const clusterLng = cluster.lngSum / cluster.count;
      const dist = distance(
        point([station.longitude, station.latitude]),
        point([clusterLng, clusterLat]),
        { units: "meters" }
      );
      if (dist < thresholdMeters && dist < nearestDist) {
        nearestCluster = cluster;
        nearestDist = dist;
      }
    }

    if (nearestCluster) {
      // Add to existing cluster
      const existingYear = nearestCluster.names.get(station.name);
      if (!existingYear || station.year > existingYear) {
        nearestCluster.names.set(station.name, station.year);
      }
      nearestCluster.latSum += station.latitude;
      nearestCluster.lngSum += station.longitude;
      nearestCluster.count++;
    } else {
      // Create new cluster
      const names = new Map<string, number>();
      names.set(station.name, station.year);
      clusters.push({
        names,
        latSum: station.latitude,
        lngSum: station.longitude,
        count: 1,
      });
    }
  }

  // Convert clusters to output format
  return clusters.map((cluster) => {
    // Pick canonical name: most recent year, then alphabetically
    const sortedNames = Array.from(cluster.names.entries()).sort((a, b) => {
      if (b[1] !== a[1]) return b[1] - a[1]; // Most recent year first
      return a[0].localeCompare(b[0]); // Alphabetically for ties
    });

    const canonicalName = sortedNames[0]![0];
    const aliases = sortedNames.slice(1).map(([name]) => name);

    return {
      canonicalName,
      aliases,
      latitude: cluster.latSum / cluster.count,
      longitude: cluster.lngSum / cluster.count,
    };
  });
}

async function main() {
  const clientPublicDir = path.join(gitRoot, "apps/client/public");
  const stationsPath = path.join(clientPublicDir, "stations.json");
  const geoJsonPath = path.join(
    dataDir,
    "d085e2f8d0b54d4590b1e7d1f35594c1pediacitiesnycneighborhoods.geojson"
  );

  console.log("Building stations.json from ALL CSV files (with aliases)...");
  console.log(`CSV glob: ${csvGlob}`);
  console.log(`GeoJSON: ${geoJsonPath}`);
  console.log(`Output: ${stationsPath}`);

  // Load neighborhood boundaries for geocoding
  console.log("\nLoading neighborhood boundaries...");
  const geoData = (await Bun.file(geoJsonPath).json()) as FeatureCollection<
    Polygon,
    NeighborhoodProperties
  >;
  const neighborhoods = geoData.features as NeighborhoodFeature[];
  console.log(`Loaded ${neighborhoods.length} neighborhood polygons`);

  const connection = await DuckDBConnection.create();

  // Extract all unique stations from ALL years
  // normalize_names=true merges "start station name" and "Start Station Name" into start_station_name
  console.log("\nLoading all CSVs (single scan)...");
  await connection.run(`
    CREATE TEMP TABLE raw_trips AS
    SELECT
      -- Station names (merged by normalize_names)
      start_station_name,
      end_station_name,
      -- Coordinates: modern (start_lat) and legacy (start_station_latitude)
      start_lat, start_lng, end_lat, end_lng,
      start_station_latitude, start_station_longitude,
      end_station_latitude, end_station_longitude,
      -- Timestamps: modern (started_at), Title Case (start_time), legacy (starttime)
      started_at, start_time, starttime,
      ended_at, stop_time, stoptime
    FROM read_csv_auto('${csvGlob}', union_by_name=true, normalize_names=true, all_varchar=true, null_padding=true, quote='"')
  `);

  // Validate data quality before processing
  // With all_varchar=true, all columns are VARCHAR - we COALESCE first, then cast
  console.log("Validating data...");
  const validationReader = await connection.runAndReadAll(`
    SELECT
      COUNT(*) as total_rows,
      -- Station name issues
      COUNT(*) FILTER (WHERE start_station_name IS NULL) as null_start_name,
      COUNT(*) FILTER (WHERE end_station_name IS NULL) as null_end_name,
      -- Coordinate issues (all VARCHAR now)
      COUNT(*) FILTER (WHERE start_station_name IS NOT NULL
        AND TRY_CAST(COALESCE(start_station_latitude, start_lat) AS DOUBLE) IS NULL) as null_start_lat,
      COUNT(*) FILTER (WHERE end_station_name IS NOT NULL
        AND TRY_CAST(COALESCE(end_station_latitude, end_lat) AS DOUBLE) IS NULL) as null_end_lat,
      -- Timestamp issues (all VARCHAR now)
      COUNT(*) FILTER (WHERE start_station_name IS NOT NULL AND COALESCE(
        TRY_CAST(started_at AS TIMESTAMP),
        TRY_CAST(start_time AS TIMESTAMP),
        TRY_CAST(starttime AS TIMESTAMP),
        TRY_STRPTIME(COALESCE(started_at, start_time, starttime), '%m/%d/%Y %H:%M:%S'),
        TRY_STRPTIME(COALESCE(started_at, start_time, starttime), '%m/%d/%Y %H:%M')
      ) IS NULL) as unparseable_timestamp
    FROM raw_trips
  `);

  type ValidationResult = {
    total_rows: bigint;
    null_start_name: bigint;
    null_end_name: bigint;
    null_start_lat: bigint;
    null_end_lat: bigint;
    unparseable_timestamp: bigint;
  };

  const v = validationReader.getRowObjects()[0] as ValidationResult;
  console.log(`Total rows: ${v.total_rows}`);

  const warnings: string[] = [];
  const total = Number(v.total_rows);
  const fmt = (count: bigint, msg: string) => {
    const pct = ((Number(count) / total) * 100).toFixed(2);
    return `${count} rows (${pct}%) with ${msg}`;
  };

  if (v.null_start_name > 0) warnings.push(fmt(v.null_start_name, "NULL start_station_name"));
  if (v.null_end_name > 0) warnings.push(fmt(v.null_end_name, "NULL end_station_name"));
  if (v.null_start_lat > 0) warnings.push(fmt(v.null_start_lat, "NULL start coordinates"));
  if (v.null_end_lat > 0) warnings.push(fmt(v.null_end_lat, "NULL end coordinates"));
  if (v.unparseable_timestamp > 0) warnings.push(fmt(v.unparseable_timestamp, "unparseable timestamp"));

  if (warnings.length > 0) {
    console.warn(`\nValidation warnings (rows will be skipped):\n  - ${warnings.join("\n  - ")}`);
  } else {
    console.log("No validation issues found.");
  }

  // Print total data loss summary
  const totalLoss =
    Number(v.null_start_name) +
    Number(v.null_end_name) +
    Number(v.null_start_lat) +
    Number(v.null_end_lat) +
    Number(v.unparseable_timestamp);
  const lossPct = ((totalLoss / total) * 100).toFixed(2);
  console.log(`\nTotal data loss: ${totalLoss} rows (${lossPct}%) will be skipped`);

  // With all_varchar=true, all columns are VARCHAR - we COALESCE first, then cast
  console.log("\nExtracting stations from temp table...");
  const stationsReader = await connection.runAndReadAll(`
    WITH all_stations AS (
      -- Start stations (all VARCHAR - COALESCE first, then cast)
      SELECT
        start_station_name AS name,
        TRY_CAST(COALESCE(start_station_latitude, start_lat) AS DOUBLE) AS lat,
        TRY_CAST(COALESCE(start_station_longitude, start_lng) AS DOUBLE) AS lng,
        EXTRACT(YEAR FROM COALESCE(
          TRY_CAST(started_at AS TIMESTAMP),
          TRY_CAST(start_time AS TIMESTAMP),
          TRY_CAST(starttime AS TIMESTAMP),
          TRY_STRPTIME(COALESCE(started_at, start_time, starttime), '%m/%d/%Y %H:%M:%S'),
          TRY_STRPTIME(COALESCE(started_at, start_time, starttime), '%m/%d/%Y %H:%M')
        )) AS year
      FROM raw_trips
      WHERE start_station_name IS NOT NULL

      UNION ALL

      -- End stations
      SELECT
        end_station_name AS name,
        TRY_CAST(COALESCE(end_station_latitude, end_lat) AS DOUBLE) AS lat,
        TRY_CAST(COALESCE(end_station_longitude, end_lng) AS DOUBLE) AS lng,
        EXTRACT(YEAR FROM COALESCE(
          TRY_CAST(ended_at AS TIMESTAMP),
          TRY_CAST(stop_time AS TIMESTAMP),
          TRY_CAST(stoptime AS TIMESTAMP),
          TRY_STRPTIME(COALESCE(ended_at, stop_time, stoptime), '%m/%d/%Y %H:%M:%S'),
          TRY_STRPTIME(COALESCE(ended_at, stop_time, stoptime), '%m/%d/%Y %H:%M')
        )) AS year
      FROM raw_trips
      WHERE end_station_name IS NOT NULL
    ),
    station_summary AS (
      SELECT
        name,
        MEDIAN(lat) AS latitude,
        MEDIAN(lng) AS longitude,
        MAX(year) AS max_year
      FROM all_stations
      WHERE lat IS NOT NULL AND lng IS NOT NULL
      GROUP BY name
    )
    SELECT name, latitude, longitude, max_year
    FROM station_summary
    ORDER BY name
  `);

  const rawRows = stationsReader.getRowObjectsJson() as unknown as Array<{
    name: string;
    latitude: number;
    longitude: number;
    max_year: number;
  }>;

  console.log(`  Found ${rawRows.length} unique station names across all years`);

  // Filter to NYC bounding box and convert to RawStation format
  const rawStations: RawStation[] = rawRows
    .filter((r) => {
      const inBounds =
        r.latitude >= NYC_BOUNDS.minLat &&
        r.latitude <= NYC_BOUNDS.maxLat &&
        r.longitude >= NYC_BOUNDS.minLng &&
        r.longitude <= NYC_BOUNDS.maxLng;
      if (!inBounds) {
        console.log(`  Filtered out: ${r.name} (${r.latitude.toFixed(6)}, ${r.longitude.toFixed(6)}) - outside NYC bounds`);
      }
      return inBounds;
    })
    .map((r) => ({
      name: r.name,
      latitude: r.latitude,
      longitude: r.longitude,
      year: r.max_year,
    }));

  console.log(`  ${rawStations.length} stations within NYC bounds`);

  // Cluster by coordinates
  console.log(`\nClustering stations by coordinates (threshold: ${CLUSTER_THRESHOLD_METERS}m)...`);
  const clustered = clusterStationsByCoordinates({
    stations: rawStations,
    thresholdMeters: CLUSTER_THRESHOLD_METERS,
  });
  console.log(`  Merged into ${clustered.length} physical locations`);

  const totalAliases = clustered.reduce((sum, c) => sum + c.aliases.length, 0);
  console.log(`  Total aliases: ${totalAliases} (for search matching)`);

  // Geocode each station
  console.log("\nGeocoding stations...");
  let matched = 0;
  let unmatched = 0;

  const stations: StationForSearch[] = clustered.map((c) => {
    const region = getStationRegion(c.latitude, c.longitude, neighborhoods);
    if (region.borough === "Unknown") {
      unmatched++;
      console.warn(`  ⚠ Unmatched: ${c.canonicalName} (${c.latitude.toFixed(6)}, ${c.longitude.toFixed(6)})`);
    } else {
      matched++;
    }
    return {
      name: c.canonicalName,
      aliases: c.aliases,
      latitude: c.latitude,
      longitude: c.longitude,
      borough: region.borough,
      neighborhood: region.neighborhood,
    };
  });

  console.log(`Geocoded: ${matched} matched, ${unmatched} unmatched`);

  await Bun.write(stationsPath, JSON.stringify(stations));
  console.log(`\nWrote ${stations.length} stations to ${stationsPath}`);

  connection.closeSync();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

// Builds routes.db (SQLite) with route geometries from OSRM.
//
// Prerequisites:
// - CSV files in data/**/*.csv (all years)
// - apps/client/public/stations.json (from build-stations.ts)
// - OSRM server running on localhost:5000
//
// Output:
// - output/routes.db (SQLite) with: start_station_name, end_station_name, geometry (polyline6), distance
//
// Routes are keyed by station NAME (not ID) because:
// - Station names are unique
// - Same physical route can have 6+ different ID combinations across years
// - Name-based keying gives fewer unique pairs to fetch from OSRM
//
// Resumable: If interrupted, re-run to continue from where it left off.
//
// Usage: bun run build-routes.ts [--concurrency N]
//   --concurrency N  Number of parallel OSRM requests (default: 50)
//                    Match this to OSRM's --threads for best performance.
import { DuckDBConnection } from "@duckdb/node-api";
import { Database } from "bun:sqlite";
import { mkdirSync, statSync } from "fs";
import path from "path";
import { parseArgs } from "util";
import { z } from "zod";
import { csvGlob, gitRoot, outputDir } from "./utils";

const { values } = parseArgs({
  args: Bun.argv.slice(2),
  options: {
    concurrency: { type: "string", short: "c", default: "5000" },
  },
});

const OSRM_URL = "http://localhost:5000";
const CONCURRENCY = parseInt(values.concurrency!, 10);
const WRITE_BATCH_SIZE = 5000;

const routesDbPath = path.join(outputDir, "routes.db");

// Station format from build-stations.ts
type StationFromFile = {
  name: string;
  aliases: string[];
  latitude: number;
  longitude: number;
  borough: string;
  neighborhood: string;
};

type Station = {
  name: string;
  latitude: number;
  longitude: number;
};

type StationPair = {
  startStationName: string;
  endStationName: string;
};

type StationPairWithCoords = StationPair & {
  startLat: number;
  startLng: number;
  endLat: number;
  endLng: number;
};

type Route = {
  startStationName: string;
  endStationName: string;
  geometry: string; // polyline6-encoded
  distance: number;
};

// OSRM response schemas
const OSRMSuccessResponseSchema = z.object({
  code: z.literal("Ok"),
  routes: z
    .array(
      z.object({
        geometry: z.string(),
        distance: z.number(),
      })
    )
    .min(1),
});

const OSRMErrorResponseSchema = z.object({
  code: z.string(),
  message: z.string().optional(),
});

const OSRMResponseSchema = z.union([OSRMSuccessResponseSchema, OSRMErrorResponseSchema]);
type OSRMResponse = z.infer<typeof OSRMResponseSchema>;
type OSRMSuccessResponse = z.infer<typeof OSRMSuccessResponseSchema>;

function isOSRMSuccess(response: OSRMResponse): response is OSRMSuccessResponse {
  return response.code === "Ok";
}

function fail(msg: string): never {
  console.error(`\n❌ FATAL: ${msg}`);
  process.exit(1);
}

async function loadStations(): Promise<Map<string, Station>> {
  const stationsPath = path.join(gitRoot, "apps/client/public/stations.json");
  const file = Bun.file(stationsPath);
  if (!(await file.exists())) {
    fail(`stations.json not found at ${stationsPath}. Run build-stations.ts first.`);
  }
  const stationsFromFile: StationFromFile[] = await file.json();

  // Map station name -> coordinates
  // Include both canonical names AND aliases so we can look up historical names from CSVs
  const stationMap = new Map<string, Station>();
  for (const station of stationsFromFile) {
    // Canonical name
    stationMap.set(station.name, {
      name: station.name,
      latitude: station.latitude,
      longitude: station.longitude,
    });
    // Also map aliases to same coordinates (for historical station names in CSVs)
    for (const alias of station.aliases ?? []) {
      stationMap.set(alias, {
        name: station.name, // Use canonical name for route key
        latitude: station.latitude,
        longitude: station.longitude,
      });
    }
  }
  return stationMap;
}

async function checkOSRM(): Promise<void> {
  try {
    const res = await fetch(`${OSRM_URL}/route/v1/bicycle/-73.99,40.73;-73.98,40.74`);
    if (!res.ok) fail(`OSRM test request failed: ${res.status}`);
    const json: unknown = await res.json();
    const parsed = OSRMResponseSchema.safeParse(json);
    if (!parsed.success) fail(`Invalid OSRM response: ${parsed.error.message}`);
    if (!isOSRMSuccess(parsed.data)) fail(`OSRM test failed: ${parsed.data.code}`);
  } catch {
    fail(`OSRM not reachable at ${OSRM_URL}. Start it first.`);
  }
}

async function fetchRoute(pair: StationPairWithCoords): Promise<Route | null> {
  const url = `${OSRM_URL}/route/v1/bicycle/${pair.startLng},${pair.startLat};${pair.endLng},${pair.endLat}?geometries=polyline6&overview=full`;

  try {
    const res = await fetch(url);
    const json: unknown = await res.json();

    const parsed = OSRMResponseSchema.safeParse(json);
    if (!parsed.success) return null;
    if (!isOSRMSuccess(parsed.data)) return null;

    const route = parsed.data.routes[0]!;
    // OSRM returns polyline6-encoded geometry directly - store as-is
    // Client will decode to get [lat, lng] pairs
    if (!route.geometry) return null;

    return {
      startStationName: pair.startStationName,
      endStationName: pair.endStationName,
      geometry: route.geometry,
      distance: route.distance,
    };
  } catch {
    return null;
  }
}

async function getUniquePairsFromCSVs(): Promise<StationPair[]> {
  console.log(`Reading unique station NAME pairs from CSVs using DuckDB...`);

  const connection = await DuckDBConnection.create();
  // Extract unique station NAME pairs (not IDs) from all years
  // normalize_names=true merges "start station name" and "Start Station Name" into start_station_name
  const reader = await connection.runAndReadAll(`
    SELECT DISTINCT
      start_station_name AS startStationName,
      end_station_name AS endStationName
    FROM read_csv_auto('${csvGlob}', union_by_name=true, normalize_names=true, all_varchar=true, null_padding=true, quote='"')
    WHERE start_station_name IS NOT NULL
      AND end_station_name IS NOT NULL
      AND start_station_name != end_station_name
  `);

  const pairs = reader.getRowObjectsJson() as unknown as StationPair[];
  connection.closeSync();

  return pairs;
}

async function main() {
  console.log("=== Build Routes (SQLite) ===\n");
  console.log(`Concurrency: ${CONCURRENCY}`);

  // 1. Load stations (keyed by name)
  console.log("Loading stations.json...");
  const stationMap = await loadStations();
  console.log(`  ${stationMap.size} station names loaded`);

  // 2. Check OSRM
  console.log("Checking OSRM...");
  await checkOSRM();
  console.log("  OSRM OK");

  // 3. Open/create SQLite database
  console.log("Opening routes.db...");
  mkdirSync(outputDir, { recursive: true });
  const db = new Database(routesDbPath);

  db.run(`
    CREATE TABLE IF NOT EXISTS routes (
      start_station_name TEXT NOT NULL,
      end_station_name TEXT NOT NULL,
      geometry TEXT NOT NULL,
      distance REAL NOT NULL,
      PRIMARY KEY (start_station_name, end_station_name)
    )
  `);

  // 4. Load existing routes for resume support
  const existingRoutes = new Set<string>();
  const existingRows = db.query("SELECT start_station_name || '->' || end_station_name as key FROM routes").all();
  for (const row of existingRows) {
    existingRoutes.add((row as { key: string }).key);
  }
  console.log(`  ${existingRoutes.size} routes already cached`);

  // 5. Get unique station pairs from CSVs
  const allPairs = await getUniquePairsFromCSVs();
  console.log(`  ${allPairs.length} unique pairs total`);

  // 6. Filter to pairs that need fetching
  // CSV names may be aliases - we normalize to canonical names for route keys
  const pairs: StationPairWithCoords[] = [];
  const seenKeys = new Set<string>(); // Dedupe after canonical normalization
  let missingStations = 0;

  for (const p of allPairs) {
    const start = stationMap.get(p.startStationName);
    const end = stationMap.get(p.endStationName);

    if (!start || !end) {
      missingStations++;
      continue;
    }

    // Use canonical names (from station lookup) for route key
    // This normalizes aliases like "8 Ave & W 31 St" -> "W 31 St & 8 Ave"
    const canonicalStartName = start.name;
    const canonicalEndName = end.name;
    const key = `${canonicalStartName}->${canonicalEndName}`;

    // Skip if we've already seen this canonical pair or it exists in DB
    if (seenKeys.has(key) || existingRoutes.has(key)) continue;
    seenKeys.add(key);

    pairs.push({
      startStationName: canonicalStartName,
      endStationName: canonicalEndName,
      startLat: start.latitude,
      startLng: start.longitude,
      endLat: end.latitude,
      endLng: end.longitude,
    });
  }

  if (missingStations > 0) {
    console.warn(`  ${missingStations} pairs skipped (station name not in stations.json)`);
  }
  console.log(`  ${pairs.length} pairs to fetch`);

  // Print total data loss summary
  const totalPairs = allPairs.length;
  const skippedPct = ((missingStations / totalPairs) * 100).toFixed(2);
  console.log(`\nTotal data loss: ${missingStations} pairs (${skippedPct}%) skipped due to missing stations`);

  if (pairs.length === 0) {
    console.log("\n✅ All routes already cached!");
    db.close();
    return;
  }

  // 7. Fetch routes from OSRM using worker pool
  console.log("Fetching routes from OSRM...");

  const insertStmt = db.query(`
    INSERT OR REPLACE INTO routes (start_station_name, end_station_name, geometry, distance)
    VALUES ($startStationName, $endStationName, $geometry, $distance)
  `);

  let success = 0;
  let failed = 0;
  let index = 0;
  let processed = 0;
  const startTime = Date.now();
  const pendingWrites: Route[] = [];

  const flushWrites = () => {
    if (pendingWrites.length === 0) return;
    db.transaction(() => {
      for (const route of pendingWrites) {
        insertStmt.run({
          $startStationName: route.startStationName,
          $endStationName: route.endStationName,
          $geometry: route.geometry,
          $distance: route.distance,
        });
      }
    })();
    pendingWrites.length = 0;
  };

  const updateProgress = () => {
    const elapsed = (Date.now() - startTime) / 1000;
    const rate = processed / elapsed;
    const remaining = pairs.length - processed;
    const eta = remaining / rate;
    const pct = (((existingRoutes.size + processed) / (existingRoutes.size + pairs.length)) * 100).toFixed(1);

    process.stdout.write(
      `\r  [${pct}%] ${success} ok, ${failed} failed | ${rate.toFixed(0)}/s | ETA: ${(eta / 60).toFixed(1)}min   `
    );
  };

  async function worker(): Promise<void> {
    while (index < pairs.length) {
      const currentIndex = index++;
      const pair = pairs[currentIndex]!;
      const route = await fetchRoute(pair);

      processed++;
      if (route) {
        success++;
        pendingWrites.push(route);

        // Flush to SQLite when batch size reached
        if (pendingWrites.length >= WRITE_BATCH_SIZE) {
          flushWrites();
        }
      } else {
        failed++;
      }

      // Update progress every 100 requests
      if (processed % 100 === 0) {
        updateProgress();
      }
    }
  }

  await Promise.all(Array.from({ length: CONCURRENCY }, () => worker()));

  // Flush remaining writes
  flushWrites();
  updateProgress();

  console.log();

  if (failed > 0) {
    console.warn(`⚠️  ${failed} routes failed (no OSRM path)`);
  }

  // 8. Report final stats
  const countResult = db.query("SELECT COUNT(*) as count FROM routes").get() as { count: number };
  const dbStats = statSync(routesDbPath);

  db.close();

  console.log(`\n✅ Done: ${countResult.count} routes (${(dbStats.size / 1024 / 1024).toFixed(1)} MB)`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

// Recursively extracts all .zip files in data/
// Usage: bun run unzip-data.ts
//
// Handles nested zips (e.g., yearly archives containing monthly zips)
// by looping until no more zip files are found.
//
// Tracks processed zips in .processed-zips.json for resumability.

import { exec } from "child_process";
import { globSync } from "glob";
import { stat } from "node:fs/promises";
import os from "os";
import path from "path";
import { promisify } from "util";
import { dataDir } from "./utils";

const PROCESSED_ZIPS_FILE = path.join(dataDir, ".processed-zips.json");

type ProcessedZipsData = {
  processedZips: string[];
};

async function loadProcessedZips(): Promise<Set<string>> {
  const file = Bun.file(PROCESSED_ZIPS_FILE);
  if (await file.exists()) {
    const data: ProcessedZipsData = await file.json();
    return new Set(data.processedZips);
  }
  return new Set();
}

async function saveProcessedZips(processedZips: Set<string>): Promise<void> {
  const data: ProcessedZipsData = {
    processedZips: Array.from(processedZips),
  };
  await Bun.write(PROCESSED_ZIPS_FILE, JSON.stringify(data, null, 2));
}

const execAsync = promisify(exec);
const CONCURRENCY = os.cpus().length;

function findZipFiles(dir: string): string[] {
  return globSync("**/*.zip", {
    cwd: dir,
    absolute: true,
    ignore: ["**/__MACOSX/**", "**/._*"],
  });
}

// Returns true if extraction succeeded
async function unzipFile(zipPath: string, current: number, total: number): Promise<boolean> {
  const dir = path.dirname(zipPath);
  console.log(`  [${current}/${total}] ${path.basename(zipPath)}`);
  try {
    // -x excludes macOS metadata (__MACOSX dirs and ._ resource fork files)
    await execAsync(`unzip -o -q "${zipPath}" -d "${dir}" -x "__MACOSX/*" "*/._*" "._*"`);
    return true;
  } catch (err) {
    console.error(`  Failed to extract ${zipPath}: ${err}`);
    return false;
  }
}

// Returns set of successfully extracted zips
async function unzipAll(zips: string[]): Promise<Set<string>> {
  const extracted = new Set<string>();
  let index = 0;
  let completed = 0;
  const total = zips.length;

  async function worker(): Promise<void> {
    while (index < zips.length) {
      const currentIndex = index++;
      const zipPath = zips[currentIndex]!;
      const success = await unzipFile(zipPath, ++completed, total);
      if (success) {
        extracted.add(zipPath);
      }
    }
  }

  await Promise.all(Array.from({ length: CONCURRENCY }, () => worker()));
  return extracted;
}

async function main() {
  console.log(`Scanning for .zip files in ${dataDir}...`);

  // Check if data directory exists
  try {
    const dirStat = await stat(dataDir);
    if (!dirStat.isDirectory()) {
      console.error(`Data directory not found: ${dataDir}`);
      console.error(`Create it and add your .zip files there.`);
      process.exit(1);
    }
  } catch {
    console.error(`Data directory not found: ${dataDir}`);
    console.error(`Create it and add your .zip files there.`);
    process.exit(1);
  }

  // Load previously processed zips for resumability
  const processedZips = await loadProcessedZips();
  if (processedZips.size > 0) {
    console.log(`Resuming: ${processedZips.size} zips already processed`);
  }

  // Keep extracting until no new zips found (handles nested zips)
  let iteration = 0;
  let totalExtracted = 0;

  while (true) {
    const allZips = findZipFiles(dataDir);
    const zips = allZips.filter((z) => !processedZips.has(z));
    if (zips.length === 0) break;

    iteration++;
    console.log(`\nPass ${iteration}: Found ${zips.length} new zip file(s) (concurrency: ${CONCURRENCY})`);

    const extracted = await unzipAll(zips);
    for (const zip of extracted) {
      processedZips.add(zip);
    }
    totalExtracted += extracted.size;

    // Save after each pass for resumability
    await saveProcessedZips(processedZips);
  }

  if (totalExtracted === 0) {
    console.log("\nNo zip files found.");
  } else {
    console.log(`\nDone. Extracted ${totalExtracted} zip file(s) in ${iteration} pass(es).`);
  }
}

main();

export function createThrottledSampler(options: { intervalMs: number }) {
  const { intervalMs } = options;
  let lastSampleTime = 0;

  return {
    sample: (callback: () => void) => {
      const now = performance.now();
      if (now - lastSampleTime >= intervalMs) {
        callback();
        lastSampleTime = now;
      }
    },
    reset: () => {
      lastSampleTime = 0;
    },
  };
}

